def mean(values: list[float])->float:
    if not values:raise ValueError("empty")
    return sum(values)/len(values)
print(mean([.1,.2,.3]))

def safe_divide(a,b):
    if b==0:raise ZeroDivisionError("denominator zero")
    return a/b
try:print(safe_divide(2,0))
except ZeroDivisionError as e:print("caught:",e)

